/*!
 * Bootstrap 5.3 Interactive Widget Controller (Standalone)
 */
(function() {
  'use strict';

  // Tab switching
  document.addEventListener('click', function(e) {
    const tabTrigger = e.target.closest('[data-bs-toggle="tab"], [data-bs-toggle="pill"]');
    if (!tabTrigger) return;
    e.preventDefault();

    const targetSelector = tabTrigger.getAttribute('data-bs-target') || tabTrigger.getAttribute('href');
    if (!targetSelector) return;
    const targetContent = document.querySelector(targetSelector);
    if (!targetContent) return;

    const nav = tabTrigger.closest('.nav, .nav-tabs, .nav-pills') || tabTrigger.parentElement.parentElement;
    if (nav) {
      nav.querySelectorAll('.nav-link, .active').forEach(function(el) {
        el.classList.remove('active');
        el.setAttribute('aria-selected', 'false');
      });
    }

    tabTrigger.classList.add('active');
    tabTrigger.setAttribute('aria-selected', 'true');

    const tabContainer = targetContent.parentElement;
    if (tabContainer) {
      tabContainer.querySelectorAll('.tab-pane').forEach(function(pane) {
        pane.classList.remove('show', 'active');
      });
    }

    targetContent.classList.add('show', 'active');
  });

  // Modal controller
  window.bootstrap = window.bootstrap || {};
  window.bootstrap.Modal = function(element) {
    this.element = typeof element === 'string' ? document.querySelector(element) : element;
  };
  window.bootstrap.Modal.prototype.show = function() {
    if (!this.element) return;
    this.element.style.display = 'block';
    this.element.classList.add('show');
    document.body.classList.add('modal-open');
    let backdrop = document.querySelector('.modal-backdrop');
    if (!backdrop) {
      backdrop = document.createElement('div');
      backdrop.className = 'modal-backdrop fade show';
      document.body.appendChild(backdrop);
    }
  };
  window.bootstrap.Modal.prototype.hide = function() {
    if (!this.element) return;
    this.element.style.display = 'none';
    this.element.classList.remove('show');
    document.body.classList.remove('modal-open');
    const backdrop = document.querySelector('.modal-backdrop');
    if (backdrop) backdrop.remove();
  };

  document.addEventListener('click', function(e) {
    const modalTrigger = e.target.closest('[data-bs-toggle="modal"]');
    if (modalTrigger) {
      e.preventDefault();
      const targetSelector = modalTrigger.getAttribute('data-bs-target');
      if (targetSelector) {
        const modal = new window.bootstrap.Modal(targetSelector);
        modal.show();
      }
    }

    const modalDismiss = e.target.closest('[data-bs-dismiss="modal"]');
    if (modalDismiss) {
      e.preventDefault();
      const modalEl = modalDismiss.closest('.modal');
      if (modalEl) {
        const modal = new window.bootstrap.Modal(modalEl);
        modal.hide();
      }
    }
  });

  // Dropdown toggle
  document.addEventListener('click', function(e) {
    const dropdownToggle = e.target.closest('[data-bs-toggle="dropdown"]');
    if (dropdownToggle) {
      e.preventDefault();
      const parent = dropdownToggle.parentElement;
      const menu = parent.querySelector('.dropdown-menu');
      if (menu) {
        const isOpen = menu.classList.contains('show');
        document.querySelectorAll('.dropdown-menu.show').forEach(function(m) { m.classList.remove('show'); });
        if (!isOpen) menu.classList.add('show');
      }
    } else if (!e.target.closest('.dropdown-menu')) {
      document.querySelectorAll('.dropdown-menu.show').forEach(function(m) { m.classList.remove('show'); });
    }
  });
})();

